// v23.xx (gfx39), HIS ORDER 2026-10-12 (the graphics program, item 8, the post pass): THE VIGNETTE IS BAKED AND THE PICTURE HAS
// FILM GRAIN. The HUD vignette built a fresh full-screen radial gradient every frame; it is now painted once per HUD canvas size
// into GFXVG (the same gradient, the same stops, in device pixels) and stamped with one drawImage, so the frame makes no gradient
// for it. The grain is a 256 x 256 tile of grey noise made once from a fixed hash (no stream is drawn from: no rnd, no fxr), laid
// over the world canvas as a pattern in overlay at 8 percent x EFFECT INTENSITY, stepped to a new offset 24 times a second of raid
// clock, after the weather and before the HUD. Overlay leaves black black, so nothing under the fog is lifted. POST FX OFF (CFG.gfxPost
// 0), EFFECT INTENSITY OFF, or a covered window draws no grain. Both stores are registered, so a lost context remakes them.
var GFXVG=null, GFXGR=null;
function gfxVignette(){
  var cw=(hcv&&hcv.width)|0, ch=(hcv&&hcv.height)|0, c, x, vg;
  if(!(cw>0&&ch>0)) return null;
  if(GFXVG&&GFXVG.width===cw&&GFXVG.height===ch) return GFXVG;
  c=document.createElement('canvas'); c.width=cw; c.height=ch; x=c.getContext('2d');
  if(!x) return null;
  vg=x.createRadialGradient(cw/2,ch/2,ch*.42,cw/2,ch/2,ch*.85);
  vg.addColorStop(0,'rgba(0,0,0,0)'); vg.addColorStop(1,'rgba(0,0,0,.45)');
  x.fillStyle=vg; x.fillRect(0,0,cw,ch);
  GFXVG=c; gfxStore('vignette',function(){ GFXVG=null; });
  return GFXVG;
}
function gfxGrainTile(){
  var N=256, c=document.createElement('canvas'), x, im, d, i, h, v;
  c.width=N; c.height=N; x=c.getContext('2d'); if(!x) return null;
  im=x.createImageData(N,N); d=im.data;
  for(i=0;i<N*N;i++){
    h=Math.imul(i^0x2545F491,0x9E3779B1); h^=h>>>15; h=Math.imul(h,0x85EBCA6B); h^=h>>>13;
    v=((h&255)+((h>>>8)&255))>>1;   // the mean of two bytes: a soft bell around mid grey
    v=128+(v-128)*1.6; v=v<0?0:(v>255?255:v);
    d[i*4]=v; d[i*4+1]=v; d[i*4+2]=v; d[i*4+3]=255;
  }
  x.putImageData(im,0,0);
  return c;
}
function gfxGrain(){
  var k, f, gx, gy, s, W2, H2;
  if(CFG.gfxPost===0||!wc||!cv) return false;
  if(typeof HID!=='undefined'&&HID&&HID.fromWorker) return false;
  k=(CFG.fxInt===undefined)?1:Math.max(0,Math.min(1,+CFG.fxInt||0));
  if(!(k>0)) return false;
  if(!GFXGR){ var t=gfxGrainTile(); if(!t) return false; GFXGR={c:t,p:null,x:null}; gfxStore('grain',function(){ GFXGR=null; }); }
  if(!GFXGR.p||GFXGR.x!==wc){ GFXGR.p=wc.createPattern(GFXGR.c,'repeat'); GFXGR.x=wc; }
  if(!GFXGR.p) return false;
  f=Math.floor(Math.max(0,+G.t||0)*24); gx=(f*97)&255; gy=(f*61+((f>>>8)*13))&255;
  s=Math.max(1,Math.round(cv.height/1080)); W2=cv.width/s+2; H2=cv.height/s+2;
  wc.save();
  try{
    wc.setTransform(s,0,0,s,-gx*s,-gy*s);
    wc.globalAlpha=0.08*k; wc.globalCompositeOperation='overlay'; wc.fillStyle=GFXGR.p;
    wc.fillRect(gx,gy,W2,H2);
  } finally { wc.restore(); }
  return true;
}
function gfxScreen(dt){ if(!gfxHook('screen')) return false; try{ gfxGrain(); }catch(_gg){} return true; }   // F1: grain and screen effects (gfx39)

